-- Original hierarchy_spec: 36 examples consolidated below at the IR -> view seam.
-- Proposal grouping/selection/nesting map to proposal scenarios; tree navigation,
-- metrics, labels and ports map to namespace scenarios; declutter and violations
-- map to their view transformations. Private default-restamping behavior is
-- exercised through proposal_view rather than a private helper.
local E = require('uml.edn')
local P = require('uml.domain.policy')
local H = require('uml.domain.hierarchy')
local function get(m,k) return E.get(m,E.keyword(k)) end
local function same(s,x) assert.is_true(E.equal(E.parse(s),x), E.encode(x)) end
local function box(v,id)
  for _,p in ipairs(get(v,'packages')) do for _,c in ipairs(get(p,'classes')) do if E.equal(get(c,'id'),E.keyword(id)) then return c end end end
end
local function edge(v,a,b)
  for _,e in ipairs(get(v,'edges')) do if E.equal(get(e,'from'),E.keyword(a)) and E.equal(get(e,'to'),E.keyword(b)) then return e end end
end
local function ids(xs) local r=E.vector(); for _,x in ipairs(xs) do r[#r+1]=get(x,'id') end; return r end
local function doc(s,p) return P.apply_policy(E.parse(p or '{:title "Demo" :hierarchical true :foreign [:quil :javax.swing] :order [:source :layout :ir]}'),E.parse(s)) end
local graph=[[{:classes [{:id :ir :ns "demo.ir"} {:id :source :ns "demo.source" :stereotype :interface} {:id :source.lua :ns "demo.source.lua"} {:id :layout :ns "demo.layout"} {:id :quil.core :name "quil.core" :foreign true} {:id :javax.swing :name "javax.swing" :foreign true}] :edges [{:from :source.lua :to :source :kind :implements} {:from :layout :to :ir :kind :dependency} {:from :layout :to :quil.core :kind :dependency} {:from :source.lua :to :javax.swing :kind :dependency}]}]]

describe('namespace view state', function()
  it('rolls directory metrics by function count while source files retain their own scores', function()
    local d=doc([[{:classes [{:id :source :crap {:mu 1 :max 1 :sigma 0} :killed 8 :survived 0 :level 0} {:id :source.lua :crap {:mu 8 :max 9 :sigma 2} :killed 1 :survived 1 :level 2} {:id :layout :crap {:mu 2 :max 3 :sigma 1} :killed 9 :survived 1}] :edges []}]])
    local root=H.view_at(d,E.vector()); local inner=H.view_at(d,E.parse('[:source]'))
    same('{:mu 4.5 :max 9 :sigma 3.8 :n 2}',get(box(root,'source'),'crap'))
    same('{:mu 2 :max 3 :sigma 1}',get(box(root,'layout'),'crap'))
    assert.are.equal(2,get(box(root,'source'),'level')); assert.are.equal(9,get(box(root,'source'),'killed')); assert.are.equal(1,get(box(root,'source'),'survived'))
    same('{:mu 1 :max 1 :sigma 0}',get(box(inner,'source'),'crap')); same('{:mu 8 :max 9 :sigma 2}',get(box(inner,'source.lua'),'crap'))
    assert.are.equal(8,get(box(inner,'source'),'killed')); assert.are.equal(0,get(box(inner,'source'),'survived'))
    local weighted=doc([[{:classes [{:id :engine :ops [{:crap 2} {:crap 2} {:crap 2}]} {:id :engine.layout :ops [{:crap 20}]}] :edges []}]])
    same('{:mu 6.5 :max 20 :sigma 7.8 :n 4}',get(box(H.view_at(weighted,E.vector()),'engine'),'crap'))
  end)
  it('counts unscored descendants as red and mutation gaps without inheriting into files', function()
    local d=doc([[{:classes [{:id :source :crap {:mu 1 :max 1 :sigma 0} :killed 8 :survived 0} {:id :source.lua :ops [{:name "a"} {:name "b"}]}] :edges []}]])
    local root=box(H.view_at(d,E.vector()),'source'); local inner=H.view_at(d,E.parse('[:source]'))
    same('{:mu 13.7 :max 20 :sigma 9 :n 3}',get(root,'crap')); assert.are.equal(2,get(root,'mut-gap'))
    same('{:mu 1 :max 1 :sigma 0}',get(box(inner,'source'),'crap')); assert.is_nil(get(box(inner,'source.lua'),'crap')); assert.is_nil(get(box(inner,'source.lua'),'killed'))
    local one=doc([[{:classes [{:id :source :crap {:mu 1 :max 1 :sigma 0}} {:id :source.lua}] :edges []}]])
    same('{:mu 10.5 :max 20 :sigma 9.5 :n 2}',get(box(H.view_at(one,E.vector()),'source'),'crap'))
  end)
  it('uses namespace labels except Rust files and preserves camel capitals', function()
    local d=doc([[{:classes [{:id :rust :file "src/lib.rs"} {:id :rust.main :file "src/main.rs"} {:id :rust.proto :file "src\\proto.RS"} {:id :graph-python :file "src/graph_python.lua"} {:id :tauriFs}] :edges []}]])
    local root=H.view_at(d,E.vector()); local inner=H.view_at(d,E.parse('[:rust]'))
    assert.are.equal('Rust',get(box(root,'rust'),'name')); assert.are.equal('lib.rs',get(box(inner,'rust'),'name')); assert.are.equal('main.rs',get(box(inner,'rust.main'),'name')); assert.are.equal('proto.RS',get(box(inner,'rust.proto'),'name'))
    same('[{:id :rust :name "lib.rs" :drill? false} {:id :rust.main :name "main.rs" :drill? false} {:id :rust.proto :name "proto.RS" :drill? false}]',get(box(root,'rust'),'contents'))
    assert.are.equal('GraphPython',get(box(root,'graph-python'),'name')); assert.are.equal('TauriFs',get(box(root,'tauriFs'),'name'))
  end)
  it('routes off-view dependencies into ports while keeping visible arrows and dotted boundaries', function()
    local d=E.parse([[{:classes [{:id :engine} {:id :engine.layout} {:id :engine.route} {:id :engineering} {:id :domain.ir}] :order {"" [:domain :engine] "engine" [:engine.route :engine.layout :engine]} :edges [{:from :engine.layout :to :engine.route :kind :dependency} {:from :engine.layout :to :domain.ir :kind :dependency} {:from :domain.ir :to :engine.route :kind :dependency}]}]])
    local root=H.view_at(d,E.vector()); local inner=H.view_at(d,E.parse('["engine"]'))
    same('[:domain :engine :engineering]',ids(get(get(root,'packages')[1],'classes')))
    same('[:engine.route :engine.layout :engine]',ids(get(get(inner,'packages')[1],'classes')))
    assert.is_truthy(edge(root,'engine','domain')); assert.is_truthy(edge(inner,'engine.layout','engine.route'))
    same('[{:id :domain :name "Domain"}]',get(box(inner,'engine.layout'),'out-deps')); same('[{:id :domain :name "Domain"}]',get(box(inner,'engine.route'),'in-deps'))
    assert.is_nil(box(inner,'engineering')); assert.is_nil(edge(inner,'engine.layout','domain'))
    E.assoc(d,E.keyword('omit'),E.parse('[:engine]')); local omitted=H.view_at(d,E.vector()); assert.is_nil(box(omitted,'engine')); assert.is_truthy(box(omitted,'engineering'))
  end)
  it('remaps one-level proposal groups and expands them without extra namespace wrappers', function()
    local d=doc([[{:classes [{:id :jvm.cli} {:id :jvm.sketch} {:id :game-api.core} {:id :quil.core :name "quil.core" :foreign true}] :edges [{:from :jvm.sketch :to :jvm.cli :kind :dependency} {:from :jvm.sketch :to :quil.core :kind :dependency}]}]],[[{:foreign [:quil] :proposals [{:id :split :layers [{:id :host :nses [:jvm.cli]} {:id :ui :nses [{:id :quil-swing :label "Quil/Swing" :nses [:jvm.sketch]}]} {:id :game-api :nses [:game-api]}]}]}]])
    local v=H.proposal_view(d,E.keyword('split'))
    assert.is_truthy(edge(v,'quil-swing','jvm.cli')); assert.is_truthy(edge(v,'quil-swing','quil')); assert.is_truthy(box(v,'game-api.core')); assert.is_nil(box(v,'game-api'))
    local inner=H.layer_view(d,E.keyword('split'),E.keyword('quil-swing'))
    same('[:jvm.sketch]',ids(get(get(inner,'packages')[1],'classes'))); assert.is_truthy(edge(inner,'jvm.sketch','quil')); assert.is_nil(box(inner,'jvm.cli'))
    local split=H.proposal_view(d,E.parse('{:id :explicit :layers [{:id :ui :nses [:jvm.sketch]} {:id :host :nses [:jvm.cli]}]}'))
    assert.is_truthy(edge(split,'jvm.sketch','jvm.cli')); assert.is_true(get(edge(split,'jvm.sketch','jvm.cli'),'violating'))
  end)
  it('restamps violations from selected proposal order, including default first selection', function()
    local d=doc([[{:classes [{:id :ir} {:id :layout}] :edges [{:from :ir :to :layout :kind :dependency} {:from :layout :to :ir :kind :dependency}]}]],[=[{:levels [[:ir] [:layout]] :proposals [{:id :rev :layers [{:id :engine :nses [:layout]} {:id :kernel :nses [:ir]}]}]}]=])
    local actual=H.view_at(d,E.vector()); local proposed=H.proposal_view(d)
    assert.is_true(get(edge(actual,'ir','layout'),'violating')); assert.is_nil(get(edge(actual,'layout','ir'),'violating'))
    assert.is_nil(get(edge(proposed,'ir','layout'),'violating')); assert.is_true(get(edge(proposed,'layout','ir'),'violating'))
    assert.are.equal(1,get(box(proposed,'ir'),'level')); assert.are.equal(0,get(box(proposed,'layout'),'level'))
    local collapsed=H.apply_declutter(proposed,E.keyword('arrows')); assert.is_true(get(edge(collapsed,'proposal.engine','proposal.kernel'),'violating'))
  end)
  it('keeps input IR and views unchanged across navigation and declutter', function()
    local d=doc(graph); local before=E.encode(d); local v=H.view_at(d,E.vector()); local saved=E.encode(v)
    H.apply_declutter(v,E.keyword('classes')); H.proposal_view(d); H.view_at(d,E.parse('[:source]'))
    assert.are.equal(before,E.encode(d)); assert.are.equal(saved,E.encode(v))
  end)
  it('declutters directional arrows with leaf provenance and preserves collapsed quality', function()
    local d=doc(graph,[[{:foreign [:quil :javax.swing] :proposal [{:id :kernel :label "Kernel" :nses [:ir :source]} {:id :engine :label "Engine" :nses [:layout]}]}]])
    local cs=get(d,'classes'); E.assoc(cs[1],E.keyword('crap'),E.parse('{:mu 3 :max 3 :sigma 0}')); E.assoc(cs[1],E.keyword('killed'),2); E.assoc(cs[1],E.keyword('survived'),0)
    local es=get(d,'edges'); es[#es+1]=E.parse('{:from :ir :to :layout :kind :dependency}'); es[#es+1]=E.parse('{:from :source :to :layout :kind :association}')
    local v=H.apply_declutter(H.proposal_view(d),E.keyword('arrows'))
    local e=edge(v,'proposal.kernel','proposal.engine'); assert.is_truthy(e)
    assert.are.equal(2,#get(e,'deps')); assert.is_truthy(get(e,'via-ids'))
    assert.is_truthy(get(box(v,'proposal.kernel'),'dummy?'))
    local collapsed=H.apply_declutter(H.proposal_view(d),E.keyword('classes')); assert.are.equal(1,#get(get(collapsed,'packages')[1],'classes')); assert.is_truthy(get(box(collapsed,'proposal.kernel'),'crap')); assert.are.equal(2,get(box(collapsed,'proposal.kernel'),'killed'))
    local full=H.view_at(d,E.vector()); local triangles=H.apply_declutter(full,E.keyword('triangles')); assert.is_true(get(triangles,'hide-edges')); assert.is_true(#get(triangles,'edges')>0)
    for _,mode in ipairs{'elements','classes','methods'} do local c=box(H.apply_declutter(full,E.keyword(mode)),'source'); assert.is_true(get(c,'hide-members')); assert.is_nil(get(c,'contents')); assert.is_nil(get(c,'in-deps')); assert.is_nil(get(c,'out-deps')) end
    local mode; for _,want in ipairs{'arrows','triangles','elements','classes','full'} do mode=H.next_declutter(mode); assert.are.equal(want,mode.name) end
  end)
  it('preserves named proposals, nested groups, leftovers, omission and drill views', function()
    local d=doc([[{:classes [{:id :jvm.cli} {:id :jvm.sketch} {:id :ir} {:id :spare} {:id :quil.core :name "quil.core" :foreign true}] :edges [{:from :jvm.sketch :to :jvm.cli :kind :dependency} {:from :jvm.sketch :to :quil.core :kind :dependency}]}]], [[{:foreign [:quil] :proposals [{:id :split :name "split" :omit [:ir] :layers [{:id :jvm :label "JVM" :nses [:jvm.cli {:id :outer :label "Outer" :nses [{:id :quil-swing :label "Quil/Swing" :nses [:jvm.sketch]}]}]}]}]}]])
    local v=H.proposal_view(d,E.keyword('split')); local pkgs=get(v,'packages')
    same('[:proposal.unassigned :proposal.jvm]',ids(pkgs)); assert.is_true(get(v,'proposal')); assert.are.equal(P.proposal_notice,get(v,'title'))
    same('[:spare]',ids(get(pkgs[1],'classes'))); same('[:jvm.cli :outer]',ids(get(pkgs[2],'classes')))
    assert.are.equal('Quil/Swing',get(get(box(v,'outer'),'contents')[1],'name'))
    -- Deep nested owner edges remain absent until their member boxes are visible.
    assert.is_nil(edge(v,'outer','jvm.cli'))
    assert.is_nil(box(v,'ir'))
    local group=H.find_nested_group(d,E.keyword('split'),E.keyword('quil-swing')); assert.are.equal('Quil/Swing',get(group,'label'))
    local drilled=H.layer_view(d,E.keyword('split'),E.keyword('outer'))
    same('[:quil-swing]',ids(get(get(drilled,'packages')[1],'classes')))
    local direct=H.layer_view(d,E.keyword('split'),E.keyword('proposal.jvm')); assert.are.equal('JVM',get(direct,'title'))
    assert.is_true(H.proposal_package_id(E.keyword('proposal.jvm'))); assert.is_false(H.proposal_package_id(E.keyword('jvm')))
    same('[:split]',ids(H.named_proposals(d))); assert.are.equal(1,#H.proposal_layers(d))
  end)
  it('uses actual namespace children and drills with self modules and foreign ovals', function()
    local d=doc(graph); local root=H.view_at(d,E.vector()); local inner=H.view_at(d,E.parse('[:source]'))
    same('[:source :layout :ir]',ids(get(get(root,'packages')[1],'classes')))
    same('[:source :source.lua]',ids(get(box(root,'source'),'contents')))
    assert.is_true(get(box(root,'source'),'drill?')); assert.is_true(get(box(root,'source'),'hide-members'))
    assert.is_false(get(get(box(root,'source'),'contents')[1],'drill?'))
    assert.is_truthy(edge(root,'layout','ir')); assert.is_truthy(edge(root,'layout','quil')); assert.is_truthy(edge(root,'source','javax.swing'))
    assert.is_nil(edge(root,'source','source')); assert.is_nil(get(box(root,'layout'),'out-deps'))
    assert.is_truthy(edge(inner,'source.lua','source')); assert.is_truthy(edge(inner,'source.lua','javax.swing'))
    same(':interface',get(box(inner,'source'),'stereotype'))
    same('[:javax.swing]',ids(get(inner,'foreign'))); assert.is_nil(box(inner,'layout'))
    assert.are.equal('source',get(inner,'title'))
  end)
end)
